<?php
namespace Tests\Feature;
use App\Models\{Admin,Customer,PaymentMethod,Product,ProductCategory,ProductLot,ShippingMethod}; use Illuminate\Foundation\Testing\RefreshDatabase; use Tests\TestCase;
class StockRequestTest extends TestCase { use RefreshDatabase;
 public function test_out_of_stock_request_defers_inventory_until_confirmation(): void { $customer=Customer::create(['name'=>'Shopper','email'=>'shop@example.test','password'=>'password123']); $category=ProductCategory::create(['name'=>'Category','slug'=>'category']); $product=Product::create(['category_id'=>$category->id,'name'=>'Requested item','slug'=>'requested-item','product_type'=>'simple','status'=>'active','default_selling_price'=>100]); PaymentMethod::create(['name'=>'COD','code'=>'cod','is_active'=>true]); ShippingMethod::create(['name'=>'Standard','code'=>'standard','charge'=>20,'currency'=>'BDT','is_active'=>true]); $payload=['items'=>[['product_id'=>$product->id,'quantity'=>2]],'payment_method_id'=>PaymentMethod::where('code','cod')->value('id'),'shipping_method_id'=>ShippingMethod::where('code','standard')->value('id'),'stock_request'=>true,'shipping_name'=>'Shopper','shipping_phone'=>'01700000000','shipping_address'=>'Dhaka']; $token=$customer->createToken('test',['customer:basic'])->plainTextToken; $order=$this->withToken($token)->postJson('/api/customers/orders',$payload)->assertCreated()->assertJsonPath('order.stock_request',true)->assertJsonPath('order.items.0.awaiting_stock',true)->json('order'); $admin=Admin::create(['name'=>'Admin','email'=>'admin@example.test','password'=>'password123','role'=>'admin']); $adminToken=$admin->createToken('test',['admin:orders'])->plainTextToken; $this->withToken($adminToken)->postJson("/api/admin/orders/{$order['id']}/items/{$order['items'][0]['id']}/fulfillment",['status'=>'confirmed'])->assertUnprocessable()->assertJsonValidationErrors('status'); ProductLot::create(['product_id'=>$product->id,'lot_number'=>'RESTOCK','buying_price'=>60,'selling_price'=>100,'quantity'=>2,'quantity_remaining'=>2]); $this->withToken($adminToken)->postJson("/api/admin/orders/{$order['id']}/items/{$order['items'][0]['id']}/fulfillment",['status'=>'confirmed'])->assertOk()->assertJsonPath('order.items.0.awaiting_stock',false)->assertJsonPath('order.items.0.line_cost','120.00'); $this->assertDatabaseHas('product_lots',['product_id'=>$product->id,'quantity_remaining'=>0]); }
}
